      SUBROUTINE SEXT3CC     CALCULATES THIRD-ORDER TRANSFER MATRIX FOR A SEXTUPOLEC      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'U.CIN'C------------------------------------------------------------------------------C      W2 = 2.0*K2      S = W2**2*L**3/48.      U(1,1) = S*L      U(2,1) = 4.0*S      U(3,10) = S*L      U(4,10) = 4.0*S      S = W2**2*L**4/48.      U(1,2) = S*L      U(2,2) = 5.0*S      U(3,16) = S*L      U(4,16) = 5.0*S      S = W2**2*L**5/144.      U(1,3) = S*L      U(2,3) = 6.0*S      U(3,19) = S*L      U(4,19) = 6.0*S      S = W2**2*L**6/1008.      U(1,4) = S*L      U(2,4) = 7.*S      U(3,20) = S*L      U(4,20) = 7.*S      S = W2**2*L**3/48.      U(1,8) = S*L      U(2,8) = 4.0*S      U(3,5) = S*L      U(4,5) = 4.0*S      S = 0.025*W2**2*L**4      U(1,14) = S*L      U(2,14) = 5.0*S      U(3,6) = S*L      U(4,6) = 5.0*S      S = W2**2*L**5/240.      U(1,17) = S*L      U(2,17) = 6.0*S      U(3,7) = S*L      U(4,7) = 6.0*S      S = - W2**2*L**4/240.      U(1,9) = S*L      U(2,9) = 5.0*S      U(3,11) = S*L      U(4,11) = 5.0*S      S = W2**2*L**5/360.      U(1,15) = S*L      U(2,15) = 6.0*S      U(3,12) = S*L      U(4,12) = 6.0*S      S = W2**2*L**6/1008.      U(1,18) = S*L      U(2,18) = 7.0*S      U(3,13) = S*L      U(4,13) = 7.0*S      S = 0.25*W2*L      U(1,36) = S*L      U(2,36) = 2.0*S      S = W2*L**3/24.      U(1,38) = S*L      U(2,38) = 4.0*S      S = - 0.25*W2*L      U(1,41) = S*L      U(2,41) = 2.0*S      S = - W2*L**3/24.      U(1,45) = S*L      U(2,45) = 4.0*S      S = W2*L**2/6.      U(1,37) = S*L      U(2,37) = 3.0*S      S = - W2*L**2/6.      U(1,44) = S*L      U(2,44) = 3.0*S      S = - 0.5*W2*L      U(3,39) = S*L      U(4,39) = 2.0*S      S = - W2*L**2/6.      U(3,40) = S*L      U(3,42) = S*L      U(4,40) = 3.0*S      U(4,42) = 3.0*S      S = - W2*L**3/12.      U(3,43) = S*L      U(4,43) = 4.0*S      RETURN      END